from author import *

# 本模块单独验证时 CHAPTERS 为空，C() 会把第一章编号成 01。
# 这三个模块在全课中是第 5 到第 7 章，这里按全课顺序固定编号，
# 与 build_course.py 的合并顺序完全一致。
c=C('IP数据报、分片与NAT')
c['key']='05'
S(c,'IP 数据报首部字段',[T('版本与首部长度','版本标明IPv4，首部长度按四字节为单位指出首部大小'),T('总长度与标识','总长度是首部加数据的总字节数，标识用来归并分片'),T('标志与片偏移','标志含MF和DF位，片偏移指出本片数据在原数据报中的位置')],[P('先看发送方把一块网页数据交给网络层。网络层在数据前面加上首部，形成IP数据报。首部里有版本号，说明这是IPv4还是IPv6；有首部长度，告诉接收方首部占几个四字节单位；有总长度，记录首部加数据一共多少字节。这些字段像快递单，让设备知道这包数据的格式和长度。',[1,2],['首部先说明格式和长度','版本决定按哪套规则解析'],show=2,phase='field',anchor='这些字段像快递单'),P('后面几个字段分工不同。标识是一串编号，同一个数据报切出的所有分片共用它，接收方靠它把分片归并回去。标志位里，MF表示后面还有分片，DF表示不允许分片；片偏移说明本片数据在原始数据里的位置。常考点是首部长度的单位，它按四字节计算。',[3],['标识用来归并同一数据报的分片','首部长度以四字节为单位'],phase='fragment',anchor='片偏移说明本片数据在原始数据里的位置')],['首部字段','分片字段'],visual=G('ipheader'))

S(c,'分片规则',[T('MTU','链路一次能承载的最大IP数据报长度，以太网常为1500字节'),T('8 字节单位','除最后一片外，每片数据长度必须是8字节的整数倍'),T('偏移计算','片偏移等于本片数据起点除以8，单位是8字节')],[P('数据从以太网发出，长度受链路限制。以太网一帧最多携带一千五百字节的IP数据报，这个上限叫MTU，也就是最大传输单元。若一个数据报总长超过MTU，路由器就要把它切成几片。切的时候每片配二十字节的IP首部，数据尽量取满，最后一片装剩下的部分。',[1,2],['MTU限制一次能传多长','每片都要重新加IP首部'],show=2),P('分片有两条硬规则。第一，除最后一片外，每片数据长度必须是八字节的整数倍，因为片偏移字段只记录八字节单位的个数。第二，片偏移等于本片数据起点除以八，第一片从零开始。做计算题时先算每片能装多少数据，再算偏移和MF，别把首部的二十字节算进数据里。',[3],['非最后一片的数据长度是8的倍数','先算数据量再算偏移'])],['分片规则','计算要点'])

S(c,'分片计算例题',[T('题设','总长4000字节，首部20字节，数据3980字节，MTU为1500'),T('分片大小','每片最多1480字节数据，分为1480、1480、1020三片'),T('片偏移与MF','偏移依次0、185、370，MF依次1、1、0')],[P('算一道例题。一个数据报总长四千字节，首部二十字节，数据三千九百八十字节，MTU为一千五百。每片首部占二十字节，所以每片最多装一千四百八十字节数据，一千四百八十是八的整数倍，可以直接用。三千九百八十除以一千四百八十，商二余一千零二十，切成三片。',[1,2],['先算每片数据上限1480','再拿总数据除以上限'],show=2),P('前两片各带一千四百八十字节数据，最后一片带一千零二十字节。片偏移等于起点除以八，第一片偏移零，第二片偏移一百八十五，第三片偏移三百七十。MF表示后面还有分片，前两片填一，最后一片填零。检查方法是三片数据相加等于三千九百八十。',[3],['偏移等于起点除以8','最后一片MF为0'])],['分片例题','步骤展示'])

S(c,'TTL、协议号与 ICMP',[T('TTL','每经一个路由器减一，减到0就丢弃并报错，防止分组绕圈'),T('协议号','告诉接收方上层是什么协议，ICMP为1，TCP为6，UDP为17'),T('ICMP','网络层的差错报告与控制协议，ping和traceroute都靠它')],[P('先看分组跑进环路。若路由表配错，分组可能在两台路由器之间来回转发，永远到不了终点。解决办法是首部里的TTL字段，它像一张有限的通行券，初始设为六十四，每经过一个路由器减一。减到零时，路由器丢弃这个分组，并向源主机发回一条差错消息。',[1,2],['TTL防止分组无限循环','初值由发送主机设置'],show=2),P('TTL从六十四出发，经过三个路由器后剩六十一，这是常考的小计算。协议号告诉接收方数据交给上层哪个协议，ICMP是一，TCP是六，UDP是十七。差错消息由ICMP完成，ping用它发回显请求，traceroute靠逐跳增加TTL来探测路径。注意TTL只由路由器递减。',[3],['三个路由器后TTL为61','协议号区分上层协议'])],['TTL','协议号与ICMP'])

S(c,'NAT 地址转换',[T('私有地址','内网主机用192.168等私有地址，公网不能直接路由'),T('转换表','记录内网地址端口与公网地址端口的对应关系'),T('出与回','出去改源地址端口，回来按转换表改目的地址端口')],[P('再看家庭上网的场景。手机拿到的是192.168.1.10这样的私有地址，它不能直接在公网上路由。发请求时，数据先到家里的路由器，路由器把源地址改成公网地址202.1.1.1，再把源端口换成40000。这个动作叫网络地址转换，缩写NAT。',[1,2],['私有地址不能出现在公网上','NAT同时改写地址和端口'],show=2,phase='out',anchor='路由器把源地址改成公网地址202.1.1.1'),P('路由器同时记下一行转换表，写明192.168.1.10的3000端口对应202.1.1.1的40000端口。回包到达时，路由器按转换表把目的地址改回来，再交给内网主机。这里常错的是端口，NAT不只换地址还换端口，因此也叫网络地址端口转换。',[3],['转换表记录地址与端口的对应','回包要靠转换表改回目的地址'],phase='back',anchor='路由器按转换表把目的地址改回来')],['NAT','地址转换'],visual=G('nat'))

S(c,'公网访问流程与限制',[T('访问步骤','主机选源端口，网关改写并记录，公网回包再交回内网'),T('端口复用','不同内网主机用不同端口映射，共用一个公网地址'),T('限制','外网不能主动连入，需要端口映射或打洞')],[P('把公网访问的步骤串起来。内网主机先选一个源端口，比如三千，然后把分组交给网关。网关改写源地址和源端口，写入转换表，再把分组送上网。公网服务器看到的是网关的公网地址，回包自然回到网关。网关查表，把目的地址改回内网地址，主机就收到了响应。',[1,2],['内网先出网关再上网','回包按转换表交回内网'],show=2),P('多台内网主机同时上网时，网关靠不同的端口号区分它们，这叫端口复用。限制也很明显：外网主机不能主动发起到内网主机的连接，因为转换表里没有对应记录；要让外网访问内网服务，得手动配置端口映射。做题时抓住这两点，NAT节省了公网地址，也破坏了端到端透明性。',[3],['端口复用让多台主机共用地址','外网不能主动连入内网'])],['访问流程','NAT的局限'])

S(c,'分片与TTL练习',[T('问题一','4000字节数据报，首部20字节，MTU 1500，请算分片数与各片偏移'),T('问题二','TTL从64出发，依次经过3个路由器，请写出到达时的TTL值')],[P('暂停一下，用分片和TTL规则做两个小题。第一题：一个数据报总长四千字节，首部二十字节，链路MTU为一千五百，请算出分成几片，每片的数据量和片偏移分别是多少。第二题：一个分组的TTL从六十四出发，经过三个路由器，请写出它到达目的主机时的TTL值。先自己判断，再翻页对照答案。',[1,2],['先算每片数据量再算偏移','TTL每个路由器减一'])],['分片练习'],kind='question')

S(c,'分片与TTL练习答案',[T('第一题','三片，数据1480、1480、1020，偏移0、185、370，MF为1、1、0'),T('第二题','结果为61，因为64减3等于61'),T('检查方法','三片数据相加等于3980字节，偏移乘以8加数据长度不超过3980')],[P('第一题：每片配二十字节首部，每片最多一千四百八十字节数据，总数据除以一千四百八十得二余一千零二十，共三片，数据量依次一千四百八十、一千四百八十和一千零二十，片偏移是零、一百八十五和三百七十，MF依次是一、一、零。第二题：TTL每经一个路由器减一，六十四减三等于六十一。检查方法是三片数据相加等于三千九百八十。',[1,2,3],['按每片1480字节数据计算','64减3等于61'])],['分片练习'],kind='answer')

c=C('路由与转发')
c['key']='06'
S(c,'路由器与路由表',[T('路由器','连接不同网络，收到分组后查表决定从哪个接口转发'),T('路由表项','写明目的网络、掩码、下一跳地址和出接口'),T('直连与静态','直连由接口配置自动产生，静态由管理员手工添加')],[P('先看一台路由器收到了分组。它不像交换机那样只看MAC地址，而是打开IP首部，看目的IP地址，再拿这个地址去路由表里查。路由表像一张指路牌，每条表项写明目的网络、掩码、下一跳地址和出接口。查到匹配项后，分组从对应接口转发出去，交给下一跳路由器。',[1,2],['路由器靠目的IP查表','表项包含下一跳和出接口'],show=2),P('路由表的来源分几类。直连路由由接口配置自动产生，路由器知道自己哪个接口连着哪个网段。静态路由由管理员手工添加，适合结构简单、出口固定的场合。动态路由由协议自动学习和更新。查表时先拿目的地址和掩码做与运算，结果等于表项网络才算匹配，不是看字符串像不像。',[3],['直连路由自动产生','静态路由适合小网络'])],['路由器','路由表'])

S(c,'最长前缀匹配',[T('匹配规则','目的地址与掩码按位与，结果等于表项网络才算匹配'),T('前缀长度','掩码越长网络越具体，越具体的路由越优先'),T('例题','目的192.168.1.70匹配192.168.1.64/27这条')],[P('打开路由表做一次查表。表里可能有好几条都能匹配目的地址，这时不是随便挑一条，而是选掩码最长、也就是前缀最长的那条。道理直观：前缀越长，网络范围越小，路由越具体，越贴近目的地。这个过程叫最长前缀匹配，是路由转发最核心的规则。',[1,2],['多条匹配时选前缀最长的','前缀越长网络越具体'],show=2,phase='lookup',anchor='这个过程叫最长前缀匹配'),P('走一遍例子。目的地址是192.168.1.70，表里有192.168.1.0斜杠26和192.168.1.64斜杠27两条。第一条覆盖点零到点六十三，第二条覆盖六十四到点九十五，七十落在第二条里，这条前缀更长，所以走192.168.1.64斜杠27那条。确定表项后从对应接口转发。',[3],['先判范围再比前缀长度','匹配后从对应接口转发'],phase='forward',anchor='所以走192.168.1.64斜杠27')],['最长前缀匹配','查表例题'],visual=G('route'))

S(c,'转发过程与默认路由',[T('查表','取出目的地址，按最长前缀匹配找到表项'),T('默认路由','0.0.0.0/0匹配任何目的地址，作为最后的兜底'),T('逐跳转发','每台路由器只决定下一跳，不掌握完整路径')],[P('把一次转发拆成几步。路由器收到帧，先校验并去掉帧首尾，取出IP分组，读出目的地址。然后拿目的地址查路由表，按最长前缀匹配确定出接口和下一跳。接着把TTL减一，重新计算首部校验和，再用出接口的MAC地址重新封装成帧发出去。整个过程在毫秒级内完成。',[1,2],['先拆帧再查表','转发前要重算校验和'],show=2),P('如果所有具体表项都不匹配，就用默认路由。它写作0.0.0.0斜杠0，前缀长度为零，表示任何目的地址都能匹配。所以路由表至少要有直连和默认路由才上得了网。这里常考的是逐跳转发：每台路由器只看下一跳，不负责全程，完整路径是沿途设备配合拼出来的。',[3],['没有具体匹配就走默认路由','逐跳转发由每台路由器配合'])],['转发过程','默认路由'])

S(c,'静态路由与动态路由',[T('静态路由','手工配置，不随拓扑变化，适合小网络和默认出口'),T('距离向量','路由器把整张表告诉邻居，按跳数选路'),T('链路状态','每台路由器收集全网拓扑，各自算最短路径')],[P('网络结构会变，路由也得跟上。小网络常用静态路由，管理员手写几条就够，优点是简单、可控、不额外占带宽，缺点是一旦链路断了要手动改。规模大了就靠动态路由，让路由器互相交换信息，自动算出转发表。动态路由按算法分两派，一派是距离向量，一派是链路状态。',[1,2],['静态路由简单但不会自愈','动态路由自动学习'],show=2),P('距离向量的做法是把整张路由表送给邻居，邻居再按跳数选少的那条，像传话一样扩散，收敛较慢，还可能出环路。链路状态的做法是每台路由器先收集全网的链路信息，拼出完整拓扑，再各自用最短路径算法算表，收敛快、不易成环，但更消耗内存和计算。做对比题时抓住信息范围。',[3],['距离向量传整表，收敛慢','链路状态收集拓扑，收敛快'])],['静态与动态','两类算法'])

S(c,'RIP、OSPF 与 BGP',[T('RIP','距离向量，按跳数，最大15跳，16表示不可达，每30秒更新'),T('OSPF','链路状态，用Dijkstra算最短路径，适合大型园区网'),T('BGP','自治系统之间的路径向量协议，交换的是AS路径')],[P('把三种路由协议对上号。RIP是距离向量协议，用跳数当度量，最大十五跳，十六跳就认为不可达，默认每三十秒向邻居发一次整表。它配置简单，适合小网络，但收敛慢，也撑不住大网络。OSPF是链路状态协议，用Dijkstra算法算最短路径，收敛快，适合大型园区网。',[1,2],['RIP按跳数，最大15跳','OSPF用链路状态和最短路径'],show=2),P('BGP的层次不一样，它在自治系统之间使用。自治系统就是由同一个组织管理、路由策略一致的一组网络。BGP交换的是到达某个网络要经过哪些自治系统，也就是AS路径，选路时还要看策略。常考点是范围：RIP和OSPF是内部网关协议，BGP是外部网关协议。',[3],['BGP交换AS路径','内部网关与外部网关要分清'])],['路由协议','RIP与OSPF与BGP'])

S(c,'转发中的封装变化',[T('MAC 地址逐跳变化','每经过一跳，源和目的MAC都换成当前链路的'),T('IP 地址基本不变','源和目的IP标识端到端通信，NAT除外'),T('TTL 递减','每台路由器把TTL减一，防止分组循环')],[P('看分组经过路由器时首部怎么变。分组到达时是一个帧，路由器去掉帧首部和帧尾，拿到IP分组，查表决定下一跳。转发时它要重新封装：源MAC换成自己出接口的地址，目的MAC换成下一跳接口的地址。所以MAC地址只管一段链路，每跳过一台路由器就换一次。',[1,2],['转发时帧首部会重新封装','MAC地址只管一段链路'],show=2),P('IP地址不一样。源和目的IP标识端到端的通信双方，转发过程中一般不改，只有NAT会改写。TTL每经一台路由器减一，减到零就丢弃并回ICMP差错。这三个变化是常考的辨析点：MAC变、IP不变、TTL递减。做帧结构题时，跨路由器就要想到帧首部会被换掉。',[3],['IP地址端到端基本不变','MAC变，IP不变，TTL递减'])],['封装变化','三个辨析点'])

S(c,'路由转发练习',[T('路由表甲','0.0.0.0/0走R1，192.168.1.0/26是直连'),T('路由表乙','192.168.1.64/27走R2，192.168.1.96/27走R3'),T('问题一','目的地址192.168.1.70应该走哪一条'),T('问题二','目的地址8.8.8.8应该走哪一条')],[P('暂停一下，用刚才的路由表做两个判断。表有四行：0.0.0.0斜杠0走R1，192.168.1.0斜杠26直连，192.168.1.64斜杠27走R2，192.168.1.96斜杠27走R3。第一问，192.168.1.70走哪条。第二问，8.8.8.8走哪条。先判断再翻页对照。',[1,2,3,4],['先找匹配项再比前缀长度','都不匹配时用默认路由'])],['路由练习'],kind='question')

S(c,'路由转发练习答案',[T('第一题','匹配192.168.1.64/27，走R2'),T('第二题','只匹配默认路由，走R1'),T('依据','最长前缀匹配优先，越具体的路由越优先')],[P('第一题：192.168.1.70落在192.168.1.64斜杠27里，范围是点六十四到点九十五，这条前缀最长，所以走R2。它不匹配192.168.1.0斜杠26，因为那条只覆盖点零到点六十三。第二题：8.8.8.8不匹配任何具体网段，只能匹配默认路由，所以走R1。两问都考最长前缀匹配。',[1,2,3],['70落在64到95之间','默认路由是最后兜底'])],['路由练习'],kind='answer')

c=C('传输层：UDP与TCP连接')
c['key']='07'
S(c,'传输层职责与端口号',[T('进程到进程','网络层送到主机，传输层再把数据交给具体进程'),T('端口号','16位整数，用0到65535区分主机上的不同应用'),T('知名端口','0到1023分给常用服务，HTTP用80，DNS用53')],[P('先看一台电脑同时开了浏览器和音乐播放器。数据都从同一块网卡进出，操作系统怎么知道哪份数据给浏览器、哪份给播放器，靠的就是端口号。网络层只负责把分组送到主机，传输层再加一层区分，用端口号把数据交给对应的进程，所以传输层的通信是进程到进程的。',[1,2],['端口号区分主机上的进程','网络层送到主机，传输层交给进程'],show=2),P('端口号是十六位整数，范围零到六万五千五百三十五。其中零到一千零二十三是知名端口，固定分给常用服务，比如HTTP用八十，HTTPS用四百四十三，DNS用五十三。客户端发起连接用临时端口。做题时源端口很大、目的端口是八十，就是客户端在访问网页。',[3],['知名端口范围0到1023','客户端用临时端口'])],['传输层','端口号'])

S(c,'UDP 的特点',[T('无连接','发送前不建立连接，直接把数据交给网络层'),T('不可靠','不确认、不重传，丢了就丢了'),T('开销小','首部只有8字节，适合实时和短消息场景')],[P('再看视频通话的场景。声音被切成一小段一小段，每一段装进UDP报文就发走。发送前不握手，接收方也不回确认，丢了就丢了，播放器会用算法补一补或直接跳过。这样做的好处是快，没有建立连接和等待确认的时间，延迟低，卡顿时也不会因为重传旧数据而越等越久。',[1,2],['UDP发送前不握手','丢包不重传，延迟低'],show=2),P('UDP的规矩很少。首部只有八个字节，包含源端口、目的端口、长度和校验和，没有序号和确认号。它不保证送达，不保证顺序，也不做流量控制和拥塞控制，应用收到什么算什么。所以DNS查询、视频直播、游戏这类宁可丢一点也不愿等的场合选UDP。UDP无连接、不可靠，但开销小、延迟低。',[3],['UDP首部只有8字节','实时场景更看重低延迟'])],['UDP','无连接'])

S(c,'TCP 的特点',[T('面向连接','通信前三次握手建连接，结束后四次挥手释放'),T('可靠有序','确认与重传保证数据不丢不乱，按序号重排'),T('字节流','没有消息边界，应用自己划分数据读到哪')],[P('换成下载文件的场景，就得用TCP。TCP在传数据前先建立连接，双方各自的初始序号、窗口大小都在握手时确认好。传送中每个数据段都要确认，超时没确认就重传。收到的数据按序号重新排好，再交给应用。所以TCP给人的感觉，是一条可靠、有序、不丢字节的水管。',[1,2],['TCP先建连接再传数据','确认和重传保证不丢'],show=2),P('三个特点常被拆开考。面向连接指通信前握手、结束后挥手，建立和释放都有状态。可靠有序靠序号、确认和重传，还配合流量控制与拥塞控制。字节流容易忽略：TCP不保留消息边界，应用发两次，对方可能一次读完，所以应用层要自己定长度或分隔符。对比UDP时按连接、可靠性、开销三方面说。',[3],['TCP不保留消息边界','对比UDP按三方面说'])],['TCP','可靠有序'])

S(c,'三次握手',[T('第一次握手','客户端发SYN，序号1000，进入SYN-SENT状态'),T('第二次握手','服务器回SYN加ACK，序号5000，确认号1001'),T('第三次握手','客户端回ACK，确认号5001，双方进入连接建立')],[P('看连接建立的过程。客户端先发一个SYN报文，把自己的初始序号一千带过去，表示想和你建立连接。服务器收到后回一个SYN加ACK，既确认对方的序号一千，也就是确认号是一千零一，又带上自己的初始序号五千。第二步是两次握手合成一次，双方各报各的序号。',[1,2],['客户端先发SYN报序号','服务器回SYN加ACK'],show=2,phase='syn',anchor='确认号是一千零一'),P('第三步，客户端再回一个确认号五千零一的ACK，表示我收到你的序号五千了。到这里连接建立，双方都确认了对方的收发能力，才开始传数据。如果只做两次握手，服务器无法确认客户端收到了自己的序号，也防不住旧的重复报文误建连接。三次刚好够，也不浪费。',[3],['第三次ACK确认服务器序号','三次握手确认双方收发能力'],phase='established',anchor='客户端再回一个确认号五千零一')],['三次握手','建连接'],visual=G('handshake'))

S(c,'四次挥手与 TIME_WAIT',[T('FIN 与 ACK','主动方发FIN，被动方先回ACK，再发自己的FIN'),T('半关闭','一方停止发送后，另一方还可以继续发数据'),T('TIME_WAIT','主动关闭方等2MSL，保证最后ACK送到并清掉旧报文')],[P('连接用完要释放。假设客户端先关，它发一个FIN，序号两千，表示没有数据要发了。服务器先回ACK，确认号两千零一，但它可能还有数据没发完，所以等数据发完再发一个FIN，序号六千。客户端回ACK，确认号六千零一。整个过程四个报文，因此叫四次挥手。',[1,2],['主动方发FIN表示不再发送','服务器可能还有数据要发'],show=2),P('四次挥手的关键在半关闭。TCP两个方向独立关闭，一方发了FIN只是这个方向不再发数据，另一个方向还可以继续发，所以中间的ACK和FIN不能合并。主动关闭方进入TIME_WAIT状态，等两倍报文最大生存时间，也就是2MSL。这样有两个作用：保证最后那个ACK能到达，以及让旧连接的残留报文消失。',[3],['两个方向独立关闭','TIME_WAIT等待2MSL'])],['四次挥手','TIME_WAIT'])

S(c,'握手挥手例题',[T('题设','客户端SYN序号1000，服务器SYN加ACK序号5000'),T('序号','服务器确认号1001，客户端第三次ACK确认号5001'),T('状态','客户端SYN-SENT，服务器SYN-RCVD，之后都进入ESTABLISHED')],[P('把序号算一遍。握手时序号不是随便写的，服务器回ACK，确认号等于对方的序号加一，所以客户端序号一千，服务器确认号就是一千零一，意思是前一千字节我收到了，下面从一千零一开始。服务器自己的初始序号是五千，客户端第三次握手时确认号就是五千零一。',[1,2],['确认号等于对方序号加一','ACK确认的是下一个期望字节'],show=2),P('挥手同理，客户端FIN序号两千，服务器ACK确认号两千零一；服务器FIN序号六千，客户端ACK确认号六千零一。常错的地方有两个：一是确认号忘了加一；二是以为SYN和FIN要额外占序号，其实它们各占一个序号位置。记状态时抓住谁先发SYN，谁先进SYN-SENT。',[3],['FIN同样占一个序号','先发SYN的一方进SYN-SENT'])],['握手例题','序号与状态'])

S(c,'握手挥手练习',[T('题设','客户端SYN序号1000，服务器SYN加ACK序号5000'),T('问题一','服务器确认号是多少，客户端第三次握手的确认号是多少'),T('问题二','说明挥手为什么需要四次而不是三次')],[P('暂停一下，用序号规则做两个小题。第一题：客户端发送SYN，序号是一千，服务器回复SYN加ACK，序号是五千，请写出服务器的确认号和客户端第三次握手的确认号。第二题：说明挥手为什么需要四次，而不是两次或三次。先自己判断，再翻页对照答案。',[1,2,3],['确认号等于对方序号加一','挥手四次与半关闭有关'])],['握手练习'],kind='question')

S(c,'握手挥手练习答案',[T('第一题','服务器确认号1001，客户端第三次ACK确认号5001'),T('第二题','TCP半关闭，两个方向分别关闭，ACK与FIN不能合并'),T('检查方法','确认号等于对方序号加一，SYN和FIN各占一个序号')],[P('第一题：服务器确认号等于客户端序号加一，是一千零一；客户端第三次ACK的确认号等于服务器序号加一，是五千零一。第二题：TCP是全双工的，两个方向各自关闭，一方发FIN只表示这个方向不再发送数据，另一方可能还有数据要发，所以ACK和FIN不能合并。检查时记住SYN和FIN各占一个序号，确认号加一。',[1,2,3],['服务器ack为1001','第三次ack为5001'])],['握手练习'],kind='answer')
